// Parity with the 20 Hz design model: the shared weapon formulas against the numbers testing/realtime.py prints. The
// tables are the same ones packages/shared/test/weapons.test.ts pins, generated by `python3 testing/weapon_reference.py`;
// paste them here too when the design numbers change.
import {
  attackInterval, backlashPerSwing, damagePerHit, FACTION_IDS, FACTIONS, WEAPON_IDS,
  type FactionId, type WeaponId,
} from "@raid/shared";

