/** Fire's backlash per enemy swing: the same for every enemy faction, 200 / (1 + boost). */
export const BACKLASH: Readonly<Record<WeaponId, number>> = {
  sword: 93.023255813954, axe: 142.857142857143, bow: 102.564102564103, wand: 121.212121212121, shield: 125.000000000000,
};

export interface ParityRow {
  faction: FactionId;
  weapon: WeaponId;
  interval: { shared: number; reference: number };
  perHit: { shared: number; reference: number };
  /** Fire's backlash per swing of an enemy of this faction holding this weapon. */
  backlash: { shared: number; reference: number };
}

export interface ParityReport {
  rows: ParityRow[];
  maxIntervalDiff: number;
  maxPerHitDiff: number;
  maxBacklashDiff: number;
  /** The largest absolute difference of all three. */
  maxDiff: number;
}

export function parityReport(): ParityReport {
  const rows: ParityRow[] = [];
  let maxIntervalDiff = 0;
  let maxPerHitDiff = 0;
  let maxBacklashDiff = 0;
  for (const f of FACTION_IDS) {
    for (const w of WEAPON_IDS) {
      const ref = REFERENCE.find(([rf, rw]) => rf === f && rw === w);
      if (!ref) throw new Error(`no reference row for ${f} ${w}`);
      const row: ParityRow = {
        faction: f,
        weapon: w,
        interval: { shared: attackInterval(FACTIONS[f], w), reference: ref[2] },
        perHit: { shared: damagePerHit(FACTIONS[f], w), reference: ref[3] },
        backlash: { shared: backlashPerSwing(FACTIONS.fire.params.backlash!, FACTIONS[f], w), reference: BACKLASH[w] },
      };
      maxIntervalDiff = Math.max(maxIntervalDiff, Math.abs(row.interval.shared - row.interval.reference));
      maxPerHitDiff = Math.max(maxPerHitDiff, Math.abs(row.perHit.shared - row.perHit.reference));
      maxBacklashDiff = Math.max(maxBacklashDiff, Math.abs(row.backlash.shared - row.backlash.reference));
      rows.push(row);
    }
  }
  return { rows, maxIntervalDiff, maxPerHitDiff, maxBacklashDiff, maxDiff: Math.max(maxIntervalDiff, maxPerHitDiff, maxBacklashDiff) };
}

const pad = (s: string, n: number): string => s.padStart(n);

/** The parity block: every faction x weapon, shared next to reference, and the largest differences. */
export function formatParity(report: ParityReport): string {
  const lines: string[] = [];
  lines.push("Parity with testing/realtime.py (shared weapon formulas, k = 1; reference / shared; backlash is Fire's, per enemy swing)");
  lines.push(`${"faction".padEnd(10)}${"weapon".padEnd(8)}${pad("interval ref", 14)}${pad("shared", 14)}${pad("per-hit ref", 14)}${pad("shared", 14)}${pad("backlash ref", 14)}${pad("shared", 14)}`);
  for (const r of report.rows) {
    lines.push(
      `${r.faction.padEnd(10)}${r.weapon.padEnd(8)}` +
      `${pad(r.interval.reference.toFixed(9), 14)}${pad(r.interval.shared.toFixed(9), 14)}` +
      `${pad(r.perHit.reference.toFixed(9), 14)}${pad(r.perHit.shared.toFixed(9), 14)}` +
      `${pad(r.backlash.reference.toFixed(6), 14)}${pad(r.backlash.shared.toFixed(6), 14)}`,
    );
  }
  lines.push(
    `max |diff|: interval ${report.maxIntervalDiff.toExponential(2)}, per-hit ${report.maxPerHitDiff.toExponential(2)}, ` +
    `backlash ${report.maxBacklashDiff.toExponential(2)}  ->  overall ${report.maxDiff.toExponential(2)}`,
  );
  return lines.join("\n");
}
